INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(1091, 'koKR', 'Młot z Zul\'Farrak$B$BAby stworzyć Młot z Zul\'Farrak, należy najpierw udać się do Ołtarza Zula i zdobyć święty młotek od trollowej strażniczki.$B$BNastępnie należy zanieść święty młotek do ołtarza na szczycie trollowego miasta Jintha\'Alor.$B$BUżycie świętego młotka przy ołtarzu nasyci go mocą i przemieni w Młot z Zul\'Farrak.$B', 0);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(3622, 'koKR', 'Jak śmiesz wchodzić do mojego sanktuarium!', '', 0),
(3745, 'koKR', 'Ruszajmy naprzód!', '', 0),
(3785, 'koKR', 'Dobra, idę!', '', 0),
(3801, 'koKR', 'Pomocy!$B$BJeśli mnie stąd wyciągniesz, wysadzę drzwi prowadzące do wodza Zul\'Farrak!', '', 0),
(3803, 'koKR', 'Musimy zabić więcej trolli! Zabij ich dość, a wysadzę drzwi do trollowego wodza!', '', 0),
(3804, 'koKR', 'Dzięki, $n. Gdyby nie ty, na pewno bylibyśmy już trupami! Teraz od wodza trolli dzielą nas tylko tamte drzwi...', '', 0),
(3806, 'koKR', 'Pomocy! Trolle pojmały mnie i moich ludzi i zamierzają złożyć nas w ofierze!$B$BWyciągnij nas stąd, a dam ci, co tylko zechcesz.', '', 0),
(3807, 'koKR', 'Nie ma czasu na gadanie! Musimy myśleć o tych trollach!', '', 0),
(3808, 'koKR', 'Wielkie dzięki, $n. Bez ciebie nie dalibyśmy rady. A, i jeśli wcześniej wspomniałem coś o odwdzięczeniu się za ratunek, to... możesz o tym zapomnieć!', '', 0),
(3811, 'koKR', 'Spadam stąd!', '', 0),
(3882, 'koKR', 'Co? Jak śmiesz tak do mnie mówić?!?', '', 0),
(3884, 'koKR', 'Po tym wszystkim, co razem przeszliśmy? No to wiedz, że i tak cię nie lubiłem!!', '', 0),
(4005, 'koKR', 'Eraka no Kimbul$BBóg Tygrysów, Pan Bestii, Król Kotów, Zguba Zwierzyny$B$BUeetay no Mueh\'zala$BBóg Śmierci, Ojciec Snu, Syn Czasu, Przyjaciel Nocy.', '', 0),
(4166, 'koKR', 'Obiad przybył, moje piękne dzieci. Rozszarpcie ich na strzępy!', '', 0),
(4177, 'koKR', 'Powstańcie i brońcie swego pana!', '', 0),
(4178, 'koKR', 'Dzieci Sula obronią swego pana. Powstań raz jeszcze, Sul\'lithuz!', '', 0),
(6221, 'koKR', 'Niech pochłoną cię piaski!', '', 0),
(6222, 'koKR', 'Padnij!', '', 0),
(6223, 'koKR', 'Niech rozpoczną się egzekucje!', '', 0),
(6224, 'koKR', 'Sprawiedliwości stało się zadość!', '', 0),
(6225, 'koKR', 'Ta pustynia być moja!', '', 0),
(6226, 'koKR', 'Giń, obcy!', '', 0),
(6227, 'koKR', 'Poczuj furię piasków!', '', 0),
(6228, 'koKR', 'Piaskowa Furia rządzi niepodzielnie!', '', 0);
